// Inline, CSS-animated marketplace (pazaryeri) illustrations (Codex SVGs in
// ./svg, generated by `node scripts/build-ikas-visuals.mjs marketplace`). Same
// contract as CustomEcomArtwork: final state in the HTML, motion opt-in via
// IkasMotionScope (`ikas-visible` once, `ikas-in-view` for loops; mounted by
// CustomEcommerceMotionScope), CSS under "marketplace visuals" in globals.css,
// reduced motion shows the end state. Seller A is turquoise, Seller B saffron.

import { BuildingStorefrontIcon } from '@heroicons/react/24/outline';
import { MARKETPLACE_VISUALS, type MarketplaceVisualName } from './generated';

interface MarketplaceArtworkProps {
  name: MarketplaceVisualName;
  /** Accessible description; omit for purely decorative use. */
  label?: string;
  /** HTML labels for `slot-*` boxes (keyed by slot id). */
  slotLabels?: Record<string, string>;
  /** Keep ambient loops running while on screen. */
  loop?: boolean;
  className?: string;
}

export default function MarketplaceArtwork({ name, label, slotLabels, loop = false, className = '' }: MarketplaceArtworkProps) {
  const visual = MARKETPLACE_VISUALS[name];
  const slots = visual.slots as Record<string, { left: number; top: number; width: number; height: number }>;
  return (
    <figure
      data-ikas-reveal=""
      className={`mp-art mp-art--${name} relative m-0 ${className}`}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
    >
      <div data-ikas-loop={loop ? '' : undefined} className="mv-art" dangerouslySetInnerHTML={{ __html: visual.markup }} />
      {Object.entries(slots).map(([id, box]) => {
        const style = { left: `${box.left}%`, top: `${box.top}%`, width: `${box.width}%`, height: `${box.height}%` };
        if (id === 'slot-store-mark') {
          return <span key={id} aria-hidden="true" className="mv-slot mv-slot-store-mark absolute flex items-center gap-1 whitespace-nowrap text-[clamp(9px,1.2vw,13px)] font-bold text-gray-900" style={style}><BuildingStorefrontIcon className="h-[1.25em] w-[1.25em] shrink-0 text-heritage-turquoise-deep" />{slotLabels?.[id] ?? 'Pazaryeriniz'}</span>;
        }
        const text = slotLabels?.[id];
        return text ? <span key={id} aria-hidden="true" className={`mv-slot mv-${id} absolute flex items-center whitespace-nowrap text-[clamp(8px,1.15vw,12.5px)] font-semibold leading-tight text-gray-700`} style={style}>{text}</span> : null;
      })}
    </figure>
  );
}
